import { afterEach, describe, expect, it, vi } from 'vitest';
import { chmod, copyFile, lstat, mkdtemp, open, readFile, readlink, rm, symlink, link, truncate, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { execFileSync } from 'node:child_process';
import { createFeedbackStore, toStored, validateFeedback, type FeedbackStoreOptions } from '../../src/journey-beta/feedback.js';
import { at, DA, H7, realSource, uuid } from './helpers.js';

// Synthetic fixtures only; no field observations are generated by production code.
const NOW = at('2026-10-16', '14:30:00');
const dirs: string[] = [];
const stores: ReturnType<typeof createFeedbackStore>[] = [];
async function setup(extra: Partial<FeedbackStoreOptions> = {}) {
  const dir = await mkdtemp(join(tmpdir(), 'feedback-storage-')); dirs.push(dir);
  await chmod(dir, 0o700);
  const options = { dir, maxFileBytes: 65536, maxPerDay: 100, clock: () => NOW, ...extra };
  const store = createFeedbackStore(options); stores.push(store);
  return { dir, options, store };
}
function record(id = 1, now = NOW) {
  const source = realSource();
  const checked = validateFeedback({ v: 1, reportId: uuid(id), kind: 'timing_quality', consent: { storeForModelImprovement: true }, modelVersion: source.dataVersion,
    context: { line: 1, originId: H7, destinationId: DA, serviceDate: '2026-10-16' }, timingQuality: 'close' },
  { nowSec: NOW / 1000, catalog: source.catalog, modelVersion: source.dataVersion, horizonDays: 7 });
  if (!checked.ok) throw new Error(checked.issues.join(','));
  return toStored(checked.value, { receivedAtEpoch: now / 1000, modelVersionMatches: true, comparison: { tripMatch: 'not_provided', modelEventAt: null, deltaSeconds: null } });
}
afterEach(async () => {
  for (const store of stores.splice(0)) await store.flush().catch(() => undefined);
  for (const dir of dirs.splice(0)) await rm(dir, { recursive: true, force: true });
});

describe('durable bounded feedback JSONL', () => {
  it('rejects internally contradictory numerical comparisons, never upgrading a qualitative claim', async () => {
    const { store } = await setup();
    const invalid = record();
    invalid.comparison = { tripMatch: 'matched', modelEventAt: '2026-10-16T14:00:00+03:30', deltaSeconds: 0 };
    expect(await store.append(invalid)).toBe('unavailable');
    expect(store.failed).toBe(false); // Bad caller data is not a disk fault.
    expect(await store.append(record(2))).toBe('stored');
  });
  it('restores exact closed-store backup bytes, duplicate index, and rejection counts', async () => {
    const { store, dir, options } = await setup();
    expect(await store.append(record())).toBe('stored'); store.reject('invalid_payload'); await store.flush();
    const backup = await setup(); await backup.store.flush();
    const names = ['feedback-2026-10.jsonl', 'rejections-2026-10.json'];
    for (const name of names) await copyFile(join(dir, name), join(backup.dir, name));
    const restored = createFeedbackStore({ ...options, dir: backup.dir }); stores.push(restored);
    expect(await restored.append(record())).toBe('duplicate');
    expect(await restored.exportRecords(() => undefined)).toBe(1);
    for (const name of names) expect(await readFile(join(backup.dir, name))).toEqual(await readFile(join(dir, name)));
  });
  it('completes short writes without splitting records and fails closed on a torn write', async () => {
    const { store, dir, options } = await setup();
    const probe = await open(join(dir, 'probe'), 'wx', 0o600); const proto = Object.getPrototypeOf(probe); await probe.close(); await rm(join(dir, 'probe'));
    const original = proto.write; let writes = 0, tear = false;
    const spy = vi.spyOn(proto, 'write').mockImplementation(async function(this: { fd: number }, ...args: unknown[]) {
      const path = await readlink(`/proc/self/fd/${this.fd}`);
      if (!path.endsWith('.jsonl')) return original.apply(this, args);
      writes++;
      if (tear && writes > 1) throw new Error('synthetic_torn_write');
      const [buffer, offset, length] = args as [Buffer, number, number];
      return original.call(this, buffer, offset, Math.min(length, 23));
    });
    try {
      expect(await store.append(record())).toBe('stored'); expect(writes).toBeGreaterThan(1);
      expect(JSON.parse((await readFile(join(dir, 'feedback-2026-10.jsonl'), 'utf8')).trim()).reportId).toBe(uuid(1));
      tear = true; writes = 0;
      expect(await store.append(record(2))).toBe('unavailable'); expect(store.failed).toBe(true);
    } finally { spy.mockRestore(); }
    const tornBytes = await readFile(join(dir, 'feedback-2026-10.jsonl'));
    await store.flush().catch(() => undefined);
    const next = createFeedbackStore(options); stores.push(next);
    expect(await next.append(record())).toBe('unavailable');
    expect(await readFile(join(dir, 'feedback-2026-10.jsonl'))).toEqual(tornBytes);
  });
  it('serializes concurrent appends, closes only after pending writes, and preserves private modes', async () => {
    const { store, dir } = await setup();
    const writes = Array.from({ length: 12 }, (_, i) => store.append(record(i + 1)));
    const closing = store.flush();
    expect(await Promise.all(writes)).toEqual(Array(12).fill('stored'));
    await closing;
    const text = await readFile(join(dir, 'feedback-2026-10.jsonl'), 'utf8');
    expect(text.trim().split('\n').length).toBe(12);
    expect((await lstat(dir)).mode & 0o777).toBe(0o700);
    expect((await lstat(join(dir, 'feedback-2026-10.jsonl'))).mode & 0o777).toBe(0o600);
    expect(await store.append(record(99))).toBe('unavailable');
  });
  it('restores duplicate and UTC daily quotas after restart', async () => {
    const { store, options } = await setup({ maxPerDay: 1 });
    expect(await store.append(record())).toBe('stored'); await store.flush();
    const restarted = createFeedbackStore(options); stores.push(restarted);
    expect(await restarted.append(record())).toBe('duplicate');
    expect(await restarted.append(record(2))).toBe('full');
  });
  it('does not ACK duplicates or writes when a retained file is corrupt or torn', async () => {
    for (const suffix of ['{"bad":true}\n', '{"reportId":', '\n', '{}\n']) {
      const { store, options, dir } = await setup();
      expect(await store.append(record())).toBe('stored'); await store.flush();
      const path = join(dir, 'feedback-2026-10.jsonl');
      const original = await readFile(path, 'utf8');
      await writeFile(path, original + suffix, { mode: 0o600 });
      const restarted = createFeedbackStore(options); stores.push(restarted);
      expect(await restarted.append(record())).toBe('unavailable');
      expect(await readFile(path, 'utf8')).toBe(original + suffix);
      expect(restarted.failed).toBe(true);
    }
  });
  it('uses the actual total retained bytes across months, not an in-memory monthly counter', async () => {
    const bytes = Buffer.byteLength(JSON.stringify(record()) + '\n');
    let now = NOW;
    const { store, options } = await setup({ maxFileBytes: bytes * 3, maxTotalBytes: bytes * 2 + 100, clock: () => now });
    expect(await store.append(record())).toBe('stored'); await store.flush();
    now = at('2026-11-01', '14:30:00');
    const next = createFeedbackStore(options); stores.push(next);
    expect(await next.append(record(2, now))).toBe('stored');
    expect(await next.append(record(3, now))).toBe('full');
    expect(await next.diskBytes()).toBeLessThanOrEqual(options.maxTotalBytes!);
  });
  it('fails closed on competing live stores and permits restart after close', async () => {
    const { store, options } = await setup();
    expect(await store.append(record())).toBe('stored');
    const competitor = createFeedbackStore(options); stores.push(competitor);
    expect(await competitor.append(record(2))).toBe('unavailable');
    await competitor.flush().catch(() => undefined); await store.flush();
    const restarted = createFeedbackStore(options); stores.push(restarted);
    expect(await restarted.append(record(2))).toBe('stored');
  });
  it('excludes a real second process and leaves a crashed-process lock fail-closed', async () => {
    const { store, options } = await setup(); expect(await store.append(record())).toBe('stored');
    const code = `import { createFeedbackStore } from './src/journey-beta/feedback.ts'; const s=createFeedbackStore({...${JSON.stringify({ dir: options.dir, maxFileBytes: options.maxFileBytes, maxPerDay: options.maxPerDay })},clock:()=>${NOW}}); console.log(await s.append(${JSON.stringify(record(2))})); await s.flush().catch(()=>{});`;
    const result = execFileSync(process.execPath, ['--import', 'tsx', '--input-type=module', '-e', code], { encoding: 'utf8', timeout: 15000 });
    expect(result.trim()).toBe('unavailable'); await store.flush();
    const crashed = await setup(); await writeFile(join(crashed.dir, '.feedback.lock'), '999999:synthetic-stale-lock\n', { mode: 0o600 });
    expect(await crashed.store.append(record())).toBe('unavailable');
    expect(await readFile(join(crashed.dir, '.feedback.lock'), 'utf8')).toBe('999999:synthetic-stale-lock\n');
  });
  it('bounds the pending queue and retained ID window without silently forgetting IDs', async () => {
    const { store } = await setup({ maxPending: 2, maxSeenIds: 2 });
    const writes = [store.append(record(1)), store.append(record(2)), store.append(record(3))];
    expect(await Promise.all(writes)).toEqual(['stored', 'stored', 'full']);
    expect(await store.append(record(3))).toBe('full');
    expect(await store.append(record(1))).toBe('duplicate');
  });
  it('fails closed on unsafe directories, symlink files and aliased paths', async () => {
    const unsafe = await setup(); await chmod(unsafe.dir, 0o755);
    expect(await unsafe.store.append(record())).toBe('unavailable');
    const linked = await setup(); const target = join(linked.dir, 'target');
    await writeFile(target, '', { mode: 0o600 }); await symlink(target, join(linked.dir, 'feedback-2026-10.jsonl'));
    expect(await linked.store.append(record())).toBe('unavailable');
    expect(await readFile(target, 'utf8')).toBe('');
    const alias = await setup(); const aliased = createFeedbackStore({ ...alias.options, dir: alias.dir + '/.' }); stores.push(aliased);
    expect(await aliased.append(record())).toBe('unavailable');
  });
  it('allows a root-managed safe ancestor alias but locks the same physical final directory', async () => {
    if (process.getuid?.() !== 0) return; // systemd/root-managed ancestor alias policy
    const { options, dir } = await setup();
    const final = join(dir, 'feedback'); const alias = join(dir, 'state-alias');
    await symlink(dir, alias);
    const first = createFeedbackStore({ ...options, dir: join(alias, 'feedback') }); stores.push(first);
    expect(await first.append(record())).toBe('stored');
    const samePhysical = createFeedbackStore({ ...options, dir: final }); stores.push(samePhysical);
    expect(await samePhysical.append(record(2))).toBe('unavailable');
    await first.flush();
  });
  it('rejects unsafe existing file permissions and detects out-of-band changes', async () => {
    const { store, dir } = await setup();
    expect(await store.append(record())).toBe('stored');
    const path = join(dir, 'feedback-2026-10.jsonl');
    await chmod(path, 0o644);
    expect(await store.append(record(2))).toBe('unavailable');
    expect(store.failed).toBe(true);
  });
  it('persists bounded rejection codes without dropping increments queued while flushing', async () => {
    const { store, dir } = await setup();
    for (let i = 0; i < 100; i++) store.reject('invalid_payload');
    store.reject('private-user@example.invalid');
    const flushing = store.flush(); store.reject('invalid_payload');
    await flushing;
    const text = await readFile(join(dir, 'rejections-2026-10.json'), 'utf8');
    const data = JSON.parse(text);
    expect(data.counts.invalid_payload).toBe(101);
    expect(data.counts.other).toBe(1);
    expect(text).not.toContain('private-user');
  });
  it('does not drop a final rejection in the close-drain microtask gap', async () => {
    const { store, dir } = await setup(); expect(await store.append(record())).toBe('stored');
    const closing = store.flush(); queueMicrotask(() => store.reject('feedback_timeout')); await closing;
    expect(JSON.parse(await readFile(join(dir, 'rejections-2026-10.json'), 'utf8')).counts.feedback_timeout).toBe(1);
  });
  it('does not reset corrupted rejection counts on shutdown', async () => {
    const { store, dir } = await setup();
    await writeFile(join(dir, 'rejections-2026-10.json'), '{broken', { mode: 0o600 });
    store.reject('invalid_payload');
    await expect(store.flush()).rejects.toThrow();
    expect(await readFile(join(dir, 'rejections-2026-10.json'), 'utf8')).toBe('{broken');
  });
  it('can expire a wholly stale file even at the exact total-byte quota', async () => {
    let now = NOW;
    const bytes = Buffer.byteLength(JSON.stringify(record()) + '\n');
    const lockBytes = Buffer.byteLength(`${process.pid}:${'x'.repeat(36)}\n`);
    const { store, options } = await setup({ maxFileBytes: bytes + lockBytes, maxTotalBytes: bytes + lockBytes, clock: () => now });
    expect(await store.append(record())).toBe('stored'); await store.flush(); now += 31 * 86400000;
    const next = createFeedbackStore(options); stores.push(next);
    expect(await next.applyRetention()).toBe(1);
    expect(await next.append(record(2, now))).toBe('stored');
  });
  it('keeps daily intake quota after privacy deletion, later intake, and another restart', async () => {
    const { store, options } = await setup({ maxPerDay: 3 });
    expect(await store.append(record(1))).toBe('stored');
    expect(await store.deleteReports([uuid(1)])).toBe(1);
    expect(await store.append(record(2))).toBe('stored');
    await store.flush();
    const next = createFeedbackStore(options); stores.push(next);
    expect(await next.append(record(3))).toBe('stored');
    expect(await next.append(record(4))).toBe('full');
  });
  it('reads bounded metadata correctly even when the filesystem returns short reads', async () => {
    const { store, dir, options } = await setup(); store.reject('invalid_payload'); await store.flush();
    const probe = await open(join(dir, 'probe'), 'wx', 0o600); const proto = Object.getPrototypeOf(probe); await probe.close(); await rm(join(dir, 'probe'));
    const original = proto.read;
    const reads = vi.spyOn(proto, 'read').mockImplementation(function(this: unknown, ...args: unknown[]) { const [buffer, offset, length, position] = args as [Buffer, number, number, number]; return original.call(this, buffer, offset, Math.min(length, 16), position); });
    try {
      const next = createFeedbackStore(options); stores.push(next);
      expect(await next.append(record())).toBe('stored'); await next.flush();
    } finally { reads.mockRestore(); }
  });
  it('syncs the parent entry when creating a new private feedback directory', async () => {
    const { dir, options } = await setup();
    const probe = await open(join(dir, 'probe'), 'wx', 0o600); const proto = Object.getPrototypeOf(probe); await probe.close(); await rm(join(dir, 'probe'));
    const original = proto.sync; const synced: string[] = [];
    const sync = vi.spyOn(proto, 'sync').mockImplementation(async function(this: { fd: number }) { synced.push(await readlink(`/proc/self/fd/${this.fd}`)); return original.call(this); });
    try {
      const nested = createFeedbackStore({ ...options, dir: join(dir, 'feedback') }); stores.push(nested);
      expect(await nested.append(record())).toBe('stored'); expect(synced).toContain(dir); await nested.flush();
    } finally { sync.mockRestore(); }
  });
  it('re-certifies recovered file durability before returning a duplicate ACK', async () => {
    const { store, dir } = await setup();
    await writeFile(join(dir, 'feedback-2026-10.jsonl'), JSON.stringify(record()) + '\n', { mode: 0o600 });
    const probe = await open(join(dir, 'probe'), 'wx', 0o600); const proto = Object.getPrototypeOf(probe); await probe.close(); await rm(join(dir, 'probe'));
    const original = proto.sync;
    const sync = vi.spyOn(proto, 'sync').mockImplementation(async function(this: { fd: number }) { const path = await readlink(`/proc/self/fd/${this.fd}`); if (path.endsWith('feedback-2026-10.jsonl')) throw new Error('injected_recovery_sync_failure'); return original.call(this); });
    try { expect(await store.append(record())).toBe('unavailable'); expect(store.failed).toBe(true); } finally { sync.mockRestore(); }
  });
  it('requires actual file durability before ACK and fails closed after sync failure', async () => {
    const { store, dir } = await setup();
    const probe = await open(join(dir, 'probe'), 'wx', 0o600); const proto = Object.getPrototypeOf(probe); await probe.close(); await rm(join(dir, 'probe'));
    const original = proto.sync;
    const sync = vi.spyOn(proto, 'sync').mockImplementation(async function(this: { fd: number }) {
      const path = await readlink(`/proc/self/fd/${this.fd}`);
      if (path.endsWith('feedback-2026-10.jsonl')) throw new Error('injected_fsync_failure');
      return original.call(this);
    });
    try {
      expect(await store.append(record())).toBe('unavailable');
      expect(store.failed).toBe(true);
      expect(await store.append(record(2))).toBe('unavailable');
      await expect(store.flush()).rejects.toThrow();
    } finally { sync.mockRestore(); }
  });
  it('retains increments arriving during the actual rejection metadata fsync', async () => {
    const { store, dir } = await setup();
    expect(await store.append(record())).toBe('stored');
    const probe = await open(join(dir, 'probe'), 'wx', 0o600); const proto = Object.getPrototypeOf(probe); await probe.close(); await rm(join(dir, 'probe'));
    const original = proto.sync; let entered!: () => void, release!: () => void;
    const reached = new Promise<void>(r => { entered = r; }); const gate = new Promise<void>(r => { release = r; });
    let paused = false;
    const sync = vi.spyOn(proto, 'sync').mockImplementation(async function(this: { fd: number }) {
      const path = await readlink(`/proc/self/fd/${this.fd}`);
      if (!paused && path.endsWith('.tmp')) { paused = true; entered(); await gate; }
      return original.call(this);
    });
    try {
      store.reject('invalid_payload'); const closing = store.flush(); await reached;
      store.reject('invalid_payload'); store.reject('model_unavailable'); release(); await closing;
      const counts = JSON.parse(await readFile(join(dir, 'rejections-2026-10.json'), 'utf8')).counts;
      expect(counts.invalid_payload).toBe(2); expect(counts.model_unavailable).toBe(1);
    } finally { release(); sync.mockRestore(); }
  });
  it('rejects hardlinks, oversized sparse files, duplicate persisted IDs and malformed UTF-8 without modifying them', async () => {
    const hard = await setup(); const source = join(hard.dir, 'external'); await writeFile(source, '', { mode: 0o600 });
    await link(source, join(hard.dir, 'feedback-2026-10.jsonl')); await rm(source);
    // Link from outside the private directory retains nlink2.
    const other = join(hard.dir, '..', 'linked-' + hard.dir.split('/').pop());
    await link(join(hard.dir, 'feedback-2026-10.jsonl'), other);
    try { expect(await hard.store.append(record())).toBe('unavailable'); } finally { await rm(other); }
    const huge = await setup(); const hugePath = join(huge.dir, 'feedback-2026-10.jsonl');
    await writeFile(hugePath, '', { mode: 0o600 }); await truncate(hugePath, 128 * 1024 * 1024);
    expect(await huge.store.append(record())).toBe('unavailable'); expect((await lstat(hugePath)).size).toBe(128 * 1024 * 1024);
    const duplicate = await setup(); const serialized = JSON.stringify(record()) + '\n';
    await writeFile(join(duplicate.dir, 'feedback-2026-10.jsonl'), serialized.repeat(2), { mode: 0o600 });
    expect(await duplicate.store.append(record())).toBe('unavailable');
    const utf = await setup(); await writeFile(join(utf.dir, 'feedback-2026-10.jsonl'), Buffer.from([0xff, 10]), { mode: 0o600 });
    expect(await utf.store.append(record())).toBe('unavailable');
  });
  it('exposes explicit export/deletion/30-day retention hooks; never auto-removes raw records', async () => {
    let now = NOW;
    const { store, options } = await setup({ clock: () => now });
    expect(await store.append(record())).toBe('stored'); await store.flush();
    now += 31 * 86400000;
    const next = createFeedbackStore(options); stores.push(next);
    const exported: string[] = [];
    expect(await next.exportRecords(r => { exported.push(r.reportId); })).toBe(1);
    expect(exported).toEqual([uuid(1)]);
    expect(await next.applyRetention()).toBe(1);
    expect(await next.exportRecords(() => undefined)).toBe(0);
    expect(await next.append(record(2, now))).toBe('stored');
    expect(await next.deleteReports([uuid(2)])).toBe(1);
    expect(await next.exportRecords(() => undefined)).toBe(0);
  });
});
